<article class="product-card"><div class="product-visual"><a href="<?php echo e(route('product',$product)); ?>"><img loading="lazy" src="<?php echo e(asset(ltrim($product->cover,'/'))); ?>" alt="<?php echo e($product->name); ?>"></a><?php if($product->sale_price): ?><span class="sale-tag">-<?php echo e(round((1-(float)$product->sale_price/(float)$product->price)*100)); ?>%</span><?php elseif($product->is_new): ?><span class="new-tag">NOVO</span><?php endif; ?> <?php if(auth()->guard()->check()): ?><form method="post" action="<?php echo e(route('favorites.toggle',$product)); ?>" class="favorite-form"><?php echo csrf_field(); ?><button title="Favoritar" aria-label="Adicionar aos favoritos">♡</button></form><?php else: ?><a class="favorite-form" href="<?php echo e(route('login')); ?>">♡</a><?php endif; ?></div><a class="product-name" href="<?php echo e(route('product',$product)); ?>"><?php echo e($product->name); ?></a><span class="product-brand"><?php echo e($product->brand?->name ?? 'Aurora Collection'); ?></span><div class="product-price">R$ <?php echo e(number_format($product->current_price,2,',','.')); ?> <?php if($product->sale_price): ?><del>R$ <?php echo e(number_format($product->price,2,',','.')); ?></del><?php endif; ?></div><div class="product-colors"><i style="background:#d6c2a7"></i><i style="background:#1c1b1a"></i><i style="background:#dfded9"></i></div></article>
